[CmdletBinding()]
param(
    [Alias('t')][string]$Type = 'maven-project',
    [Alias('l')][string]$Language = 'java',
    [Alias('b')][string]$Boot,
    [Alias('g')][string]$Group = 'com.example',
    [Alias('a')][string]$Artifact = 'demo',
    [Alias('n')][string]$Name,
    [Alias('p')][string]$Packaging = 'jar',
    [Alias('c')][string]$Config = 'properties',
    [Alias('j')][string]$Java = '21',
    [Alias('d')][string]$Dependencies,
    [Alias('w')][string]$Workspace,
    [string]$Project = 'demo',
    [Alias('y')][string]$Python,
    [switch]$Clean
)

$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'common\toolchain.ps1')
$repo = Get-RepoRoot

if (-not $Name) { $Name = "$Group.$Artifact" }
if (-not $Workspace) { $Workspace = Join-Path $repo 'workspaces\springboot-demo' }
$targetDir = Resolve-RepoPath (Join-Path $Workspace $Project)
$tmpDir = Join-Path $repo '.tmp'
New-Item -ItemType Directory -Force -Path $tmpDir | Out-Null

if (-not $Python -or $Python -in @('python', 'python3')) { $Python = $env:CRONOVA_PYTHON }
if (-not $Python) { $Python = Get-ConfiguredCommand 'python' }
else {
    $resolvedPython = Get-Command $Python -ErrorAction SilentlyContinue
    if ($resolvedPython) { $Python = $resolvedPython.Source }
    elseif (-not (Test-Path -LiteralPath $Python -PathType Leaf)) { throw "Configured Python is not executable: $Python" }
}

function ConvertTo-InitializrValue([string]$Value) {
    # Python urllib.parse.quote(value.strip()) in the Bash reference leaves slash unescaped.
    return ([Uri]::EscapeDataString($Value.Trim())).Replace('%2F', '/')
}

function Find-ConfiguredExecutable([string]$Name) {
    $command = Get-Command $Name -ErrorAction SilentlyContinue
    if ($command) { return $command.Source }

    foreach ($pathValue in @($env:CRONOVA_WINDOWS_PATH, $env:Path)) {
        if (-not $pathValue) { continue }
        foreach ($directory in $pathValue.Split([IO.Path]::PathSeparator, [StringSplitOptions]::RemoveEmptyEntries)) {
            $candidate = Join-Path $directory.Trim().Trim('"') $Name
            if (Test-Path -LiteralPath $candidate -PathType Leaf) {
                return (Resolve-Path -LiteralPath $candidate).Path
            }
        }
    }
    return $null
}

$query = @(
    'type=' + (ConvertTo-InitializrValue $Type)
    'language=' + (ConvertTo-InitializrValue $Language)
)
if ($Boot) { $query += 'bootVersion=' + (ConvertTo-InitializrValue $Boot) }
$query += 'groupId=' + (ConvertTo-InitializrValue $Group)
$query += 'artifactId=' + (ConvertTo-InitializrValue $Artifact)
# Preserve the Bash script's existing URL contract: name is populated from Artifact.
$query += 'name=' + (ConvertTo-InitializrValue $Artifact)
$query += 'packageName=' + (ConvertTo-InitializrValue $Name)
$query += 'packaging=' + (ConvertTo-InitializrValue $Packaging)
$query += 'configFormat=' + (ConvertTo-InitializrValue $Config)
$query += 'javaVersion=' + (ConvertTo-InitializrValue $Java)
if ($Dependencies) { $query += 'dependencies=' + (ConvertTo-InitializrValue $Dependencies) }
$url = 'https://start.spring.io/starter.zip?' + ($query -join '&')

Write-Output 'Downloading Spring Boot project from start.spring.io...'
Write-Output "Using Python: $Python"
Write-Output "URL: $url"
$zipFile = Join-Path $tmpDir 'springboot-project.zip'
$curl = Find-ConfiguredExecutable 'curl.exe'
$wget = if (-not $curl) { Find-ConfiguredExecutable 'wget.exe' }
if ($curl) {
    $downloader = $curl
    $downloadArgs = @('-L', '-o', $zipFile, $url)
} elseif ($wget) {
    $downloader = $wget
    $downloadArgs = @('-O', $zipFile, $url)
} else {
    throw 'Error: curl.exe or wget.exe was not found on PATH or CRONOVA_WINDOWS_PATH.'
}
Write-Output "Using downloader: $downloader"
$downloadStdout = Join-Path $tmpDir ("springboot-download-" + [guid]::NewGuid().ToString('N') + '.stdout')
$downloadStderr = Join-Path $tmpDir ("springboot-download-" + [guid]::NewGuid().ToString('N') + '.stderr')
try {
    $downloadProcess = Start-Process -FilePath $downloader -ArgumentList (ConvertTo-NativeArgumentString $downloadArgs) -Wait -PassThru -NoNewWindow -RedirectStandardOutput $downloadStdout -RedirectStandardError $downloadStderr
    $stdout = if (Test-Path -LiteralPath $downloadStdout) { [IO.File]::ReadAllText($downloadStdout) } else { '' }
    $stderr = if (Test-Path -LiteralPath $downloadStderr) { [IO.File]::ReadAllText($downloadStderr) } else { '' }
    if ($stdout) { [Console]::Out.Write($stdout) }
    if ($stderr) { [Console]::Error.Write($stderr) }
    if ($downloadProcess.ExitCode -ne 0) {
        [Console]::Error.WriteLine("Spring Initializr download failed: program=$downloader exit_code=$($downloadProcess.ExitCode) stderr=$stderr")
        exit [int]$downloadProcess.ExitCode
    }
} finally {
    Remove-Item -LiteralPath $downloadStdout, $downloadStderr -Force -ErrorAction SilentlyContinue
}

if ($Clean) {
    Write-Output "Cleaning target directory: $targetDir"
    if (Test-Path -LiteralPath $targetDir) { Remove-Item -LiteralPath $targetDir -Recurse -Force }
}

New-Item -ItemType Directory -Force -Path $targetDir | Out-Null
Write-Output "Extracting project to $targetDir..."
Expand-Archive -LiteralPath $zipFile -DestinationPath $targetDir -Force
Write-Output "Spring Boot project downloaded and extracted to $targetDir"

[CmdletBinding()]
param(
    [Alias('a')][string]$Archetype = 'maven-archetype-quickstart',
    [Alias('v')][string]$ArchetypeVersion,
    [Alias('g')][string]$Group = 'com.example',
    [Alias('r')][string]$Artifact = 'demo',
    [Alias('k')][string]$Package,
    [Alias('j')][string]$JavaVersion = '21',
    [Alias('w')][string]$Workspace,
    [Alias('p')][string]$Project = 'demo',
    [Alias('C')][switch]$Clean
)
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'common\toolchain.ps1')
$repo = Get-RepoRoot
if (-not $Package) { $Package = $Group }
if (-not $Workspace) { $Workspace = Join-Path $repo 'workspaces\maven-demo' }
$workspaceDir = Resolve-RepoPath $Workspace
$targetDir = Join-Path $workspaceDir $Project
$workspacePathInfo = Resolve-Path $workspaceDir -ErrorAction SilentlyContinue
$absoluteWorkspace = if ($workspacePathInfo) { $workspacePathInfo.Path } else { $null }
if (-not $absoluteWorkspace) {
    New-Item -ItemType Directory -Force -Path $workspaceDir | Out-Null
    $absoluteWorkspace = (Resolve-Path $workspaceDir).Path
}
$targetDir = Join-Path $absoluteWorkspace $Project
$tmpOut = Join-Path $absoluteWorkspace ('.archetype-out-' + [guid]::NewGuid().ToString('N'))
if ($Clean) {
    Write-Output "Cleaning target directory: $targetDir"
    Remove-Item -LiteralPath $targetDir -Recurse -Force -ErrorAction SilentlyContinue
}
Remove-Item -LiteralPath $tmpOut -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force -Path $tmpOut | Out-Null
Set-JavaMavenToolchain
$maven = Get-ConfiguredCommand 'maven'
$args = @('-B', 'archetype:generate', "-DgroupId=$Group", "-DartifactId=$Artifact", "-Dpackage=$Package", '-Dversion=1.0-SNAPSHOT', "-DarchetypeArtifactId=$Archetype")
if ($ArchetypeVersion) { $args += "-DarchetypeVersion=$ArchetypeVersion" }
$args += @('-DinteractiveMode=false', "-DoutputDirectory=$tmpOut")
Write-Output "Generating Maven archetype $Archetype..."
$stdoutFile = Join-Path $tmpOut 'maven.stdout.log'
$stderrFile = Join-Path $tmpOut 'maven.stderr.log'
try {
    $process = Start-Process -FilePath $maven -ArgumentList $args -WorkingDirectory $repo -Wait -PassThru -NoNewWindow -RedirectStandardOutput $stdoutFile -RedirectStandardError $stderrFile
    Get-Content -LiteralPath $stdoutFile -ErrorAction SilentlyContinue | Write-Output
    Get-Content -LiteralPath $stderrFile -ErrorAction SilentlyContinue | Write-Output
    if ([int]$process.ExitCode -ne 0) {
        throw "Maven archetype generation failed with exit code $($process.ExitCode)"
    }
} finally {
    Remove-Item -LiteralPath $stdoutFile, $stderrFile -Force -ErrorAction SilentlyContinue
}
$generatedDir = Join-Path $tmpOut $Artifact
if (-not (Test-Path -LiteralPath $generatedDir -PathType Container)) {
    Remove-Item -LiteralPath $tmpOut -Recurse -Force -ErrorAction SilentlyContinue
    throw "Archetype did not generate expected directory: $generatedDir"
}
Remove-Item -LiteralPath $targetDir -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force -Path (Split-Path $targetDir -Parent) | Out-Null
Copy-Item -LiteralPath $generatedDir -Destination $targetDir -Recurse -Force
Remove-Item -LiteralPath $tmpOut -Recurse -Force -ErrorAction SilentlyContinue
$pom = Join-Path $targetDir 'pom.xml'
if (Test-Path -LiteralPath $pom -PathType Leaf) {
    $xml = Get-Content -LiteralPath $pom -Raw
    $changed = $false
    foreach ($tag in @('source', 'target', 'release')) {
        $pattern = "<$($tag -replace '^','maven.compiler.')>[^<]*</$($tag -replace '^','maven.compiler.')>"
        $fullTag = "maven.compiler.$tag"
        if ($xml -match "<$fullTag>[^<]*</$fullTag>") {
            $xml = [regex]::Replace($xml, "<$fullTag>[^<]*</$fullTag>", "<$fullTag>$JavaVersion</$fullTag>")
            $changed = $true
        }
    }
    if ($xml -notmatch '<maven\.compiler\.(source|target|release)>') {
        $xml = $xml -replace '</project>', "<properties><maven.compiler.source>$JavaVersion</maven.compiler.source><maven.compiler.target>$JavaVersion</maven.compiler.target></properties></project>"
        $changed = $true
    }
    if ($changed) { Set-Content -LiteralPath $pom -Value $xml -Encoding UTF8 }
}
Write-Output "Maven archetype generated successfully in $targetDir"

[CmdletBinding()]
param(
    [Alias('f')][Parameter(Mandatory=$true)][string]$PromptFile,
    [Alias('w')][string]$Workspace,
    [Alias('p')][string]$Project = 'demo',
    [Alias('k')][string]$Package = 'com.example',
    [Alias('r')][string]$ProviderId,
    [Alias('m')][string]$Model,
    [Alias('y')][string]$Python,
    [Alias('s')][switch]$IncludeSources
)
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'common\toolchain.ps1')
. (Join-Path $PSScriptRoot 'common\ai-provider.ps1')
$repo = Get-RepoRoot
if (-not $PromptFile) { throw 'Prompt file is required.' }
$promptPath = Resolve-RepoPath $PromptFile
if (-not (Test-Path -LiteralPath $promptPath -PathType Leaf)) { throw "Prompt file not found: $promptPath" }
if (-not $Workspace) { $Workspace = Join-Path $repo 'workspaces\maven-demo' }
$projectDir = Resolve-RepoPath (Join-Path $Workspace $Project)
if (-not (Test-Path -LiteralPath $projectDir -PathType Container)) { throw "Project directory not found: $projectDir" }
if (-not $Python -or $Python -in @('python','python3')) { $Python = $env:CRONOVA_PYTHON }
if (-not $Python) { $Python = Get-ConfiguredCommand 'python' }
else { $resolved = Get-Command $Python -ErrorAction SilentlyContinue; if ($resolved) { $Python = $resolved.Source } }
$baseUrl = $env:CRONOVA_AI_BASE_URL
$token = $env:CRONOVA_AI_TOKEN
$db = if ($env:CRONOVA_DB) { $env:CRONOVA_DB } else { Join-Path $repo 'data\cronova.db' }
if (-not $Model -or -not $baseUrl) {
    $provider = Resolve-AiProvider $db $ProviderId $Python
    if ($provider) { if (-not $baseUrl) {$baseUrl=$provider[0]}; if (-not $Model) {$Model=$provider[1]}; if (-not $token) {$token=$provider[2]} }
}
if (-not $Model -or -not $baseUrl) { throw 'Could not determine AI provider. Configure a default AI provider or pass -r and -m.' }
$tmp = Join-Path $repo '.tmp'; New-Item -ItemType Directory -Force -Path $tmp | Out-Null
$pomFile = Join-Path $projectDir 'pom.xml'
$pom = if (Test-Path -LiteralPath $pomFile) { Get-Content -LiteralPath $pomFile -Raw } else { '' }
if (-not $pom) { throw "pom.xml not found in project directory: $projectDir" }

$sourceContext = ''
if ($IncludeSources) {
    $javaFiles = Get-ChildItem -Path $projectDir -Recurse -Filter '*.java' -ErrorAction SilentlyContinue |
        Where-Object { $_.Length -gt 0 } |
        Sort-Object FullName
    if ($javaFiles) {
        $sourceContext = ($javaFiles | ForEach-Object {
            $relative = $_.FullName.Substring($projectDir.Length).TrimStart('\', '/')
            "--- $relative ---`n" + (Get-Content -LiteralPath $_.FullName -Raw)
        }) -join "`n`n"
    }
}

$userPrompt = Get-Content -LiteralPath $promptPath -Raw
$fullPrompt = @"
You are a Java code generator for Maven projects.
$userPrompt

Given the Maven project below, return ONLY a JSON object where:
- keys are relative file paths (e.g. "src/main/java/com/example/luhn/Luhn.java", "src/test/java/com/example/luhn/LuhnTest.java")
- values are full file contents as strings
- optional key "pom_xml" = complete updated pom.xml content ONLY if new dependencies are required; omit this key if no dependency changes are needed

Rules:
- Do NOT add <version> tags to dependencies managed by the Maven parent or BOM.
- Generate new classes for the requested feature and corresponding tests.
- Do NOT assume existing source files have specific names like App.java or AppTest.java.
- If you generate code or tests that require dependencies not present in pom.xml, you MUST return a complete updated pom_xml.
- Before omitting pom_xml, verify that every import used by the generated Java and test files is already satisfied by the current pom.xml.
- If you generate JUnit 4 or JUnit 5 style tests and the current pom.xml only contains older JUnit dependencies, you MUST update pom_xml accordingly.
- For simple Spring controller CRUD features, generate only direct in-memory controller tests that instantiate the controller class and call its methods.
- Do NOT generate tests using MockMvc, WebMvcTest, AutoConfigureMockMvc, MockBean, RestTemplate, TestRestTemplate, random ports, localhost HTTP calls, or any Spring MVC/web test infrastructure unless the user prompt explicitly requires that style.
- For controller tests, assert on the actual ResponseEntity API available in the current dependency set and on the actual return type of the controller method; do not assume List, HTTP clients, or helper methods that are not already present.
- Do NOT use `getStatusCodeValue()`. Prefer `getStatusCode().value()` or boolean/status comparisons supported by the current Spring API.
- Escape JSON string newlines as \n (one backslash followed by n); do not leave literal backslash-n text in generated file contents. Escape quotes as \".

pom.xml:
$pom

$sourceContext
"@
$fullPromptFile=Join-Path $tmp 'ai_feature_prompt.txt'; $reqFile=Join-Path $tmp 'ai_feature_request.json'; $respFile=Join-Path $tmp 'ai_feature_response.json'
Set-Content -LiteralPath $fullPromptFile -Value $fullPrompt -Encoding UTF8
Write-Output "Calling AI provider (model: $Model, url: $baseUrl)..."
$aiScript = Join-Path $repo 'internal\scripts\ai_generate_feature.py'
$stdoutFile=Join-Path $tmp 'ai_feature.stdout'; $stderrFile=Join-Path $tmp 'ai_feature.stderr'
try {
    $aiArgs=@($aiScript,$projectDir,$fullPromptFile,$reqFile,$respFile,$Model,$baseUrl)
    if($token){$aiArgs += $token}
    $process=Start-Process -FilePath $Python -ArgumentList $aiArgs -Wait -PassThru -NoNewWindow -RedirectStandardOutput $stdoutFile -RedirectStandardError $stderrFile
    $stdout=Get-Content $stdoutFile -ErrorAction SilentlyContinue; $stderr=(Get-Content $stderrFile -ErrorAction SilentlyContinue)-join [Environment]::NewLine
    $stdout | Write-Output
    if($process.ExitCode -ne 0){throw "AI feature generation failed with exit code $($process.ExitCode): $stderr"}
} finally { Remove-Item -LiteralPath $stdoutFile,$stderrFile -Force -ErrorAction SilentlyContinue }
Write-Output "AI added feature to $projectDir"

[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$Config,
    [string]$Workspace,
    [string]$Artifacts
)

$ErrorActionPreference = 'Stop'

. (Join-Path $PSScriptRoot 'common\toolchain.ps1')
$repo = Get-RepoRoot
. (Join-Path $repo 'scripts\sdlc\common\AngularConfig.ps1')

$settings = Get-AngularSdlcConfig -Config $Config
$configPath = $settings.ConfigPath
$workspacePath = if ($Workspace) { Resolve-SdlcRepoPath -Path $Workspace -RepoRoot $settings.RepoRoot } else { $settings.WorkspacePath }
$artifactsPath = if ($Artifacts) { Resolve-SdlcRepoPath -Path $Artifacts -RepoRoot $settings.RepoRoot } else { $settings.ArtifactsPath }

if ([string]::IsNullOrWhiteSpace($workspacePath)) {
    throw 'Workspace path could not be resolved from config or parameters.'
}

if ([string]::IsNullOrWhiteSpace($artifactsPath)) {
    throw 'Artifacts path could not be resolved from config or parameters.'
}

New-Item -ItemType Directory -Force -Path $workspacePath | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $artifactsPath 'logs') | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $artifactsPath 'reports') | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $artifactsPath 'metadata') | Out-Null

$configText = Get-Content -LiteralPath $configPath -Raw
if ($configText -match '(/c/Users/|/home/|/tmp/|/var/|systemd|launchd)') {
    throw 'Configuration contains a non-portable Unix/private path.'
}

if (-not $settings.ProjectId) {
    throw 'Angular config lacks project.id.'
}

if ($settings.ProjectKind -ne 'angular') {
    throw 'Config kind must be angular.'
}

$runtimeFile = Join-Path $artifactsPath 'metadata\runtime.txt'
@(
    "workspace=$workspacePath"
    "artifacts=$artifactsPath"
    "config=$configPath"
) | Set-Content -LiteralPath $runtimeFile -Encoding UTF8

$node = Get-Command 'node.exe' -ErrorAction SilentlyContinue
if (-not $node) { $node = Get-Command 'node' -ErrorAction SilentlyContinue }
if (-not $node) { throw 'Required command not found: node' }

$npm = Get-Command 'npm.cmd' -ErrorAction SilentlyContinue
if (-not $npm) { $npm = Get-Command 'npm' -ErrorAction SilentlyContinue }
if (-not $npm) { throw 'Required command not found: npm' }

$nodeVersion = (& $node.Source --version).Trim()
$npmVersion = (& $npm.Source --version).Trim()

$nodeVersion | Set-Content -LiteralPath (Join-Path $artifactsPath 'metadata\node-version.txt') -Encoding UTF8
$npmVersion | Set-Content -LiteralPath (Join-Path $artifactsPath 'metadata\npm-version.txt') -Encoding UTF8

Write-Output $nodeVersion
Write-Output $npmVersion
Write-Output "Angular configuration is valid: $configPath"

[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$Config,
    [string]$Workspace,
    [string]$Artifacts
)

$ErrorActionPreference = 'Stop'

. (Join-Path $PSScriptRoot 'common\toolchain.ps1')
$repo = Get-RepoRoot
. (Join-Path $repo 'scripts\sdlc\common\AngularConfig.ps1')

function Invoke-ContractFrontendGenerator {
    param(
        [Parameter(Mandatory=$true)][hashtable]$Settings,
        [Parameter(Mandatory=$true)][string]$WorkspacePath,
        [Parameter(Mandatory=$true)][string]$PythonPath
    )

    $apiClientMode = if ($null -eq $Settings.ApiClientMode) { '' } else { $Settings.ApiClientMode.ToString().ToLowerInvariant() }
    if ($apiClientMode -notin @('contract', 'openapi-generated')) {
        return
    }

    $generatorPath = Join-Path $Settings.RepoRoot 'scripts\sdlc\integration\generate_contract_app.py'
    $backendWorkspace = Join-Path $Settings.RepoRoot '.workspaces\springboot'
    $contractPath = Resolve-SdlcRepoPath -Path $Settings.OpenApiFile -RepoRoot $Settings.RepoRoot
    $apiBaseUrl = if ($Settings.ApiBaseUrl) { $Settings.ApiBaseUrl } else { 'http://127.0.0.1:18080/api' }
    $frontendOrigin = "http://{0}:{1}" -f $Settings.ServerHost, $Settings.ServerPort

    if (-not (Test-Path -LiteralPath $generatorPath -PathType Leaf)) {
        throw "Contract frontend generator not found: $generatorPath"
    }

    if (-not (Test-Path -LiteralPath $backendWorkspace -PathType Container)) {
        throw "Expected Spring Boot workspace for contract generation not found: $backendWorkspace"
    }

    Write-Output "Generating contract-driven Angular app in $WorkspacePath"
    Invoke-Native -FilePath $PythonPath -ArgumentList @(
        $generatorPath,
        '--contract', $contractPath,
        '--backend-workspace', $backendWorkspace,
        '--frontend-workspace', $WorkspacePath,
        '--backend-package', 'com.example.items',
        '--api-base-url', $apiBaseUrl,
        '--frontend-origin', $frontendOrigin
    ) -WorkingDirectory $Settings.RepoRoot
}

$settings = Get-AngularSdlcConfig -Config $Config
$workspacePath = if ($Workspace) { Resolve-SdlcRepoPath -Path $Workspace -RepoRoot $settings.RepoRoot } else { $settings.WorkspacePath }
$artifactsPath = if ($Artifacts) { Resolve-SdlcRepoPath -Path $Artifacts -RepoRoot $settings.RepoRoot } else { $settings.ArtifactsPath }

if ([string]::IsNullOrWhiteSpace($workspacePath)) {
    throw 'Workspace path could not be resolved from config or parameters.'
}

if ([string]::IsNullOrWhiteSpace($artifactsPath)) {
    throw 'Artifacts path could not be resolved from config or parameters.'
}

$npx = Get-Command 'npx.cmd' -ErrorAction SilentlyContinue
if (-not $npx) { $npx = Get-Command 'npx' -ErrorAction SilentlyContinue }
if (-not $npx) { throw 'Required command not found: npx' }

$node = Get-Command 'node.exe' -ErrorAction SilentlyContinue
if (-not $node) { $node = Get-Command 'node' -ErrorAction SilentlyContinue }
if (-not $node) { throw 'Required command not found: node' }

$python = Get-Command 'py.exe' -ErrorAction SilentlyContinue
if (-not $python) { $python = Get-Command 'py' -ErrorAction SilentlyContinue }
if (-not $python) { throw 'Required command not found: py' }

$npm = Get-Command 'npm.cmd' -ErrorAction SilentlyContinue
if (-not $npm) { $npm = Get-Command 'npm' -ErrorAction SilentlyContinue }
if (-not $npm) { throw 'Required command not found: npm' }

$appName = if ($settings.AppName) { $settings.AppName } else { 'item-portal' }
$cliVersion = if ($settings.AngularCliVersion) { $settings.AngularCliVersion } else { 'latest' }

function Test-PackageScript {
    param(
        [Parameter(Mandatory=$true)][string]$PackageJsonPath,
        [Parameter(Mandatory=$true)][string]$ScriptName
    )

    if (-not (Test-Path -LiteralPath $PackageJsonPath -PathType Leaf)) {
        return $false
    }

    $packageJson = Get-Content -LiteralPath $PackageJsonPath -Raw | ConvertFrom-Json
    if ($null -eq $packageJson.scripts) {
        return $false
    }

    return $null -ne ($packageJson.scripts.PSObject.Properties[$ScriptName])
}

function Test-PackageDependency {
    param(
        [Parameter(Mandatory=$true)][string]$PackageJsonPath,
        [Parameter(Mandatory=$true)][string]$DependencyName
    )

    if (-not (Test-Path -LiteralPath $PackageJsonPath -PathType Leaf)) {
        return $false
    }

    $packageJson = Get-Content -LiteralPath $PackageJsonPath -Raw | ConvertFrom-Json
    $hasDevDependency = ($null -ne $packageJson.devDependencies) -and ($null -ne $packageJson.devDependencies.PSObject.Properties[$DependencyName])
    $hasDependency = ($null -ne $packageJson.dependencies) -and ($null -ne $packageJson.dependencies.PSObject.Properties[$DependencyName])
    return $hasDevDependency -or $hasDependency
}

function Ensure-LintSetup {
    param(
        [Parameter(Mandatory=$true)][string]$WorkspacePath,
        [Parameter(Mandatory=$true)][string]$CliVersion,
        [Parameter(Mandatory=$true)][string]$NpxPath
    )

    $packageJsonPath = Join-Path $WorkspacePath 'package.json'
    if (Test-PackageScript -PackageJsonPath $packageJsonPath -ScriptName 'lint') {
        return
    }

    Write-Output "Adding angular-eslint to Angular workspace: $WorkspacePath"
    Invoke-Native -FilePath $NpxPath -ArgumentList @('--yes', "@angular/cli@$CliVersion", 'add', "@angular-eslint/schematics@$CliVersion", '--skip-confirmation') -WorkingDirectory $WorkspacePath
}

function Ensure-TestBrowserSetup {
    param(
        [Parameter(Mandatory=$true)][string]$WorkspacePath,
        [Parameter(Mandatory=$true)][string]$NpmPath
    )

    $packageJsonPath = Join-Path $WorkspacePath 'package.json'
    if (Test-PackageDependency -PackageJsonPath $packageJsonPath -DependencyName 'puppeteer') {
        return
    }

    Write-Output "Adding Puppeteer Chromium for Angular unit tests: $WorkspacePath"
    Invoke-Native -FilePath $NpmPath -ArgumentList @('install', '--save-dev', '--package-lock-only', 'puppeteer@24') -WorkingDirectory $WorkspacePath
}

$packageJsonPath = Join-Path $workspacePath 'package.json'
if (Test-Path -LiteralPath $packageJsonPath -PathType Leaf) {
    Write-Output "Angular project already exists: $workspacePath"
    Invoke-ContractFrontendGenerator -Settings $settings -WorkspacePath $workspacePath -PythonPath $python.Source
    Ensure-LintSetup -WorkspacePath $workspacePath -CliVersion $cliVersion -NpxPath $npx.Source
    Ensure-TestBrowserSetup -WorkspacePath $workspacePath -NpmPath $npm.Source
    $packageLockPath = Join-Path $workspacePath 'package-lock.json'
    if (-not (Test-Path -LiteralPath $packageLockPath -PathType Leaf)) {
        Write-Output "Generating missing package-lock.json: $workspacePath"
        Invoke-Native -FilePath $npm.Source -ArgumentList @('install', '--package-lock-only', '--ignore-scripts') -WorkingDirectory $workspacePath
    }
    exit 0
}

New-Item -ItemType Directory -Force -Path $workspacePath | Out-Null

$cliDirectory = $workspacePath
$repoRootWithSeparator = $settings.RepoRoot.TrimEnd('\') + '\'
if ($workspacePath.StartsWith($repoRootWithSeparator, [System.StringComparison]::OrdinalIgnoreCase)) {
    $cliDirectory = $workspacePath.Substring($repoRootWithSeparator.Length)
}

Invoke-Native -FilePath $npx.Source -ArgumentList @(
    '--yes',
    "@angular/cli@$cliVersion",
    'new',
    $appName,
    '--directory', $cliDirectory,
    '--routing',
    '--style=scss',
    '--standalone',
    '--skip-git',
    '--package-manager=npm',
    '--skip-install'
) -WorkingDirectory $settings.RepoRoot

Invoke-ContractFrontendGenerator -Settings $settings -WorkspacePath $workspacePath -PythonPath $python.Source
Ensure-LintSetup -WorkspacePath $workspacePath -CliVersion $cliVersion -NpxPath $npx.Source
Ensure-TestBrowserSetup -WorkspacePath $workspacePath -NpmPath $npm.Source
Invoke-Native -FilePath $npm.Source -ArgumentList @('install', '--package-lock-only', '--ignore-scripts') -WorkingDirectory $workspacePath

Write-Output "Angular scaffold created in $workspacePath"

[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$Config,
    [string]$Artifacts
)

$ErrorActionPreference = 'Stop'

$scriptRoot = $PSScriptRoot

try {
    & (Join-Path $scriptRoot 'fullstack-start-backend.ps1') -Config $Config -Artifacts $Artifacts
    & (Join-Path $scriptRoot 'fullstack-start-frontend.ps1') -Config $Config -Artifacts $Artifacts
    & (Join-Path $scriptRoot 'fullstack-wait-services.ps1') -Config $Config -Artifacts $Artifacts
    & (Join-Path $scriptRoot 'fullstack-run-playwright-e2e.ps1') -Config $Config -Artifacts $Artifacts
} finally {
    & (Join-Path $scriptRoot 'fullstack-stop-services.ps1') -Config $Config -Artifacts $Artifacts
}

[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$Config,
    [string]$Artifacts
)

$ErrorActionPreference = 'Stop'

. (Join-Path $PSScriptRoot 'common\toolchain.ps1')
$repo = Get-RepoRoot
. (Join-Path $repo 'scripts\sdlc\common\SpringbootConfig.ps1')

$settings = Get-SpringbootSdlcConfig -Config $Config
$configPath = $settings.ConfigPath
$artifactsPath = if ($Artifacts) { Resolve-SdlcRepoPath -Path $Artifacts -RepoRoot $settings.RepoRoot } else { $settings.ArtifactsPath }

if ([string]::IsNullOrWhiteSpace($artifactsPath)) {
    throw 'Artifacts path could not be resolved from config or parameters.'
}

New-Item -ItemType Directory -Force -Path (Join-Path $artifactsPath 'metadata') | Out-Null

Set-JavaMavenToolchain
[void](Get-ConfiguredCommand 'java')

$configText = Get-Content -LiteralPath $configPath -Raw
if ($configText -match '(/c/Users/|/home/|/tmp/|/var/|systemd|launchd)') {
    throw 'Configuration contains a non-portable Unix/private path.'
}

if (-not $settings.ProjectId) {
    throw 'Spring Boot config lacks project.id.'
}

if ($settings.ProjectKind -ne 'springboot') {
    throw 'Config kind must be springboot.'
}

$javaVersionFile = Join-Path $artifactsPath 'metadata\java-version.txt'
$toolchainRuntimeFile = Join-Path $artifactsPath 'metadata\toolchain-runtime.txt'

$java = Get-ConfiguredCommand 'java'
$base = Join-Path ([IO.Path]::GetTempPath()) ("springboot-validate-" + [guid]::NewGuid().ToString('N'))
$stdoutFile = "$base.out"
$stderrFile = "$base.err"
try {
    $process = Start-Process -FilePath $java -ArgumentList '-version' -Wait -PassThru -NoNewWindow -RedirectStandardOutput $stdoutFile -RedirectStandardError $stderrFile
    $stdout = if (Test-Path -LiteralPath $stdoutFile) { [IO.File]::ReadAllText($stdoutFile) } else { '' }
    $stderr = if (Test-Path -LiteralPath $stderrFile) { [IO.File]::ReadAllText($stderrFile) } else { '' }
    ($stdout + $stderr).Trim() | Set-Content -LiteralPath $javaVersionFile -Encoding UTF8
    if ($stdout) { [Console]::Out.Write($stdout) }
    if ($stderr) { [Console]::Error.Write($stderr) }
    if ([int]$process.ExitCode -ne 0) {
        throw 'java -version failed'
    }
} finally {
    Remove-Item -LiteralPath $stdoutFile, $stderrFile -Force -ErrorAction SilentlyContinue
}

Write-ToolchainRuntime $toolchainRuntimeFile
Write-Output "Spring Boot configuration is valid: $configPath"
